import{_ as s,C as r,o as l,c as o,ag as t,E as n}from"./chunks/framework.CtWPcAmt.js";const w=JSON.parse('{"title":"Seller Account Health","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-account-health.md","filePath":"sellers/seller-account-health.md","lastUpdated":1786111645000}'),i={name:"sellers/seller-account-health.md"};function c(h,e,d,g,u,p){const a=r("ImagePopup");return l(),o("div",null,[e[0]||(e[0]=t('<h1 id="seller-account-health" tabindex="-1">Seller Account Health <a class="header-anchor" href="#seller-account-health" aria-label="Permalink to &quot;Seller Account Health&quot;">​</a></h1><p>Account Health is a single, honest read on how a seller is doing — built from <strong>cancellations</strong>, <strong>customer feedback</strong>, and <strong>flags</strong>. Sellers see it in their panel; the admin sees it per seller and marketplace-wide, and uses it to keep the marketplace reliable.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>The three metrics behind the score</li><li>How the score and its bands are calculated</li><li>How and when it refreshes</li></ul></div><h2 id="the-seller-s-view" tabindex="-1">The seller&#39;s view <a class="header-anchor" href="#the-seller-s-view" aria-label="Permalink to &quot;The seller&#39;s view&quot;">​</a></h2><p>A seller opens <strong>Performance → Account Health</strong>. It shows an <strong>Overall Health</strong> verdict, a <strong>Health Score</strong> out of 100 on an Unhealthy → At Risk → Healthy gauge, and three metric cards.</p>',5)),n(a,{src:"/images/seller-account-health/account-health.png",alt:"Seller account health page"}),e[1]||(e[1]=t('<ul><li><strong>Order Cancellation Rate</strong> — cancelled units over the <strong>last 30 days</strong>, with a target (for example, below 2.5%). Lower is better.</li><li><strong>Customer Feedback</strong> — the seller&#39;s average rating across <strong>approved</strong> reviews (last 90 days), target 4.0 and above. Shows &quot;No Data&quot; until there are reviews.</li><li><strong>Flags</strong> — flags customers raised against the store in the <strong>last 90 days</strong>, measured against the marketplace&#39;s red-flag limit.</li></ul><h2 id="how-the-score-works" tabindex="-1">How the score works <a class="header-anchor" href="#how-the-score-works" aria-label="Permalink to &quot;How the score works&quot;">​</a></h2><p>Each metric is graded <strong>good / warning / critical</strong> against its thresholds, and the three combine into a <strong>0–100</strong> score split into bands:</p><ul><li><strong>0–33 Unhealthy</strong>, <strong>34–66 At Risk</strong>, <strong>67–100 Healthy</strong>.</li></ul><p>The overall verdict follows the worst-performing metric that has data, so one bad area is surfaced rather than averaged away. Cancellation always counts; feedback counts once there are reviews; flags count while flagging is enabled. The <strong>cancellation-rate thresholds</strong> (warning and critical percentages) are set by the admin under <strong>Configure → Marketplace → Moderation &amp; Health → Account Health</strong>.</p><h2 id="refreshing" tabindex="-1">Refreshing <a class="header-anchor" href="#refreshing" aria-label="Permalink to &quot;Refreshing&quot;">​</a></h2><ul><li><strong>Seller</strong> — the page shows when it was last updated and a <strong>Refresh now</strong> button, with a short cooldown between manual refreshes (and a countdown to the next allowed refresh). A <strong>How is this calculated?</strong> guide explains the maths interactively.</li><li><strong>Admin</strong> — can refresh a seller&#39;s health any time (no cooldown) from the sellers list, individually or in bulk, and a scheduled job keeps every seller&#39;s health current.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The fastest wins are usually <strong>fewer cancellations</strong> (keep stock accurate so you don&#39;t cancel orders) and <strong>more approved reviews</strong>. Both feed directly into the score — and into <a href="/sellers/featured-sellers">Featured Sellers</a>.</p></div>',8))])}const f=s(i,[["render",c]]);export{w as __pageData,f as default};
